using System;using System.IO;using System.Text;using SPICA.Formats.CtrGfx;using SPICA.Formats.CtrGfx.Animation;using SPICA.Formats.CtrGfx.Model;
class Program{
static void Check(bool v,string msg){if(!v)throw new Exception(msg);}
static int Ptr(byte[] b,int p)=>p+BitConverter.ToInt32(b,p);
static int Main(string[] args){try{
bool left=args[0].Contains("left-");float px=left?-8.61f:0,py=left?1f:3.8f,pz=left?.735f:0;var s=Gfx.Open(args[0]);var h=s.ToH3D();byte[] reference=File.ReadAllBytes(args[1]);int ra=Encoding.ASCII.GetString(reference).IndexOf("CANM"),rm=Ptr(reference,Ptr(reference,ra+28)+40);Check(s.Models.Count==1&&s.Textures.Count==3&&s.SkeletalAnimations.Count==1&&s.MaterialAnimations.Count==0&&s.VisibilityAnimations.Count==0,"One continuous skeletal animation only");
foreach(var m in s.Models){var sk=(GfxModelSkeletal)m;Check(sk.Skeleton.Bones.Count==5,"Minish hierarchy");var bs=sk.Skeleton.Bones;Check(bs[0].Name=="Scene root"&&bs[1].Name=="COMMON"&&bs[2].Name=="ForgeTurnCoin"&&bs[3].Name=="ForgeBackdrop"&&bs[4].Name=="ForgeWordmark","Opaque-first dictionary order");Check(bs[1].Child==bs[2]&&bs[2].NextSibling==bs[3]&&bs[3].NextSibling==bs[4]&&bs[4].NextSibling==null,"Linked hierarchy matches dictionary order");foreach(var b in sk.Skeleton.Bones){if(b.Name=="ForgeTurnCoin")Check((int)b.BillboardMode==0&&Math.Abs(b.Translation.X-px)<.0001f&&Math.Abs(b.Translation.Z-pz)<.0001f&&Math.Abs(b.Translation.Y-py)<.0001f,"Central coin axis");if(b.Name=="ForgeBackdrop"||b.Name=="ForgeWordmark")Check((int)b.BillboardMode==5&&b.Translation.Length()==0,"Fixed artwork");}}
int meshes=0,triangles=0,faces=0;foreach(var m in h.Models)foreach(var mesh in m.Meshes){meshes++;var vs=mesh.GetVertices();foreach(var sub in mesh.SubMeshes){Check(sub.BoneIndicesCount==1,"Rigid geometry");foreach(var i in sub.Indices)Check(i<vs.Length,"Index bounds");triangles+=sub.Indices.Length/3;}if(m.Materials[mesh.MaterialIndex].Name=="Face"){faces++;foreach(var v in vs){float sign=v.Normal.Z;Check(Math.Abs(Math.Abs(sign)-1)<.0001f&&Math.Abs(v.Position.Z-sign*.45f)<.0001f,"Two real opposite faces");Check(Math.Abs(v.TexCoord0.X-(.5f+sign*v.Position.X/6.82f))<.0001f,"Correct back-logo orientation");}}}
Check(meshes==7&&triangles==324&&faces==2,"Complete two-sided 3D coin");var anim=s.SkeletalAnimations[0];Check(anim.FramesCount==BitConverter.ToSingle(reference,ra+20)&&anim.FramesCount==270&&anim.Elements.Count==1,"Minish loop");var t=(GfxAnimTransform)anim.Elements[0].Content;Check(anim.Elements[0].Name=="ForgeTurnCoin","Target");var curves=new[]{t.ScaleX,t.ScaleY,t.ScaleZ,t.RotationY,t.TranslationX,t.TranslationY};int[] fields={20,24,28,36,48,52};for(int axis=0;axis<curves.Length;axis++){var a=curves[axis];int curve=Ptr(reference,rm+fields[axis]),seg=Ptr(reference,curve+20),count=BitConverter.ToInt32(reference,seg+12);Check(a.KeyFrames.Count==count,"Reference key count");for(int i=0;i<count;i++)Check(a.KeyFrames[i].Frame==BitConverter.ToSingle(reference,seg+20+i*8)&&Math.Abs(a.KeyFrames[i].Value-(axis==4?px:axis==5?py:BitConverter.ToSingle(reference,seg+24+i*8)))<.00001f,"Matches packaged Minish curve");}Check(t.TranslationZ.KeyFrames.Count==2&&Math.Abs(t.TranslationZ.KeyFrames[0].Value-pz)<.00001f&&Math.Abs(t.TranslationZ.KeyFrames[1].Value-pz)<.00001f,"No depth orbit");
Console.WriteLine("PASS complete independent CGFX: one central two-sided 3D coin, seven rigid meshes, 324 triangles; continuous native Y rotation; scale/X/Y translation/rotation curves equal packaged Minish; Z translation fixed zero; no sprite, pose-bank, material or visibility animation");return 0;
}catch(Exception e){Console.WriteLine(e);return 1;}}}
